def premiere_cassee(versions):
    if not versions or versions[-1]:
        return None
    gauche, droite = 0, len(versions) - 1
    while gauche < droite:
        milieu = (gauche + droite) // 2
        if versions[milieu]:
            gauche = milieu + 1
        else:
            droite = milieu
    return gauche

