def appliquer(prix, pct):
    return prix - prix * pct / 100


def prix_final(prix, remise_pct):
    reduit = appliquer(prix, remise_pct)
    return round(reduit)

def ligne_coupable(lignes):
    for i, ligne in enumerate(lignes):
        try:
            int(ligne.split(";")[1])
        except (ValueError, IndexError):
            return i
    return None


def test_ligne_coupable():
    assert ligne_coupable([]) is None
    assert ligne_coupable(["riz;2", "huile;1"]) is None
    assert ligne_coupable(["riz;2", "huile;un", "sel;3"]) == 1
    assert ligne_coupable(["riz;-2"]) is None


# Vérification fournie : ne la modifie pas.
MUTANTS = [
    lambda ls: None,
    lambda ls: next((i for i, l in enumerate(ls) if not l.split(";")[1].isdigit()), None) if ls else None,
    lambda ls: 0 if ls else None,
]


def evaluer_tests():
    global ligne_coupable
    original = ligne_coupable
    test_ligne_coupable()
    resultats = []
    for mutant in MUTANTS:
        ligne_coupable = mutant
        try:
            test_ligne_coupable()
            resultats.append("raté")
        except Exception:
            resultats.append("détecté")
    ligne_coupable = original
    return resultats
